import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Listen,
  Prop,
  State,
} from '@stencil/core';
import { Alignment, NavigationSizes } from '../../../types';
import { AriaAttributes, extractAriaAttributes } from '../../../utils/a11y-helper';
import { createMenuObserver, handleActiveMenuAttributes, observeAllMenus } from '../../../utils/menu-helper';

@Component({
  tag: 'groupui-local-top-navigation',
  styleUrl: 'local-top-navigation.scss',
  shadow: true,
})
export class LocalTopNavigation implements ComponentInterface {
  /**
   * sets the size of the items
   */
  @Prop({ reflect: true }) readonly size: NavigationSizes = 's';

  /**
   * Deactivates the active state management.
   */
  @Prop({ reflect: true }) readonly manualMode: boolean = false;

  /**
   * sets the alignment of the top navigation items
   */
  @Prop({ reflect: true }) readonly alignment: Alignment = 'center';

  /**
   * Emitted when the component has loaded.
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * Emitted when the active item changes
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  @State() private navItemElements: HTMLGroupuiLocalTopNavigationItemElement[] = [];
  @State() private activeItemIndex: number = -1;
  @State() private ariaAttributes: AriaAttributes;
  @Element() host: HTMLElement;

  private menuObserver: MutationObserver;

  componentWillLoad(): void {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.updateNavItems();
    this.menuObserver = createMenuObserver();
  }

  componentDidLoad() {
    handleActiveMenuAttributes(this.host, this.menuObserver);
    this.groupuiDidLoad.emit();
  }

  disconnectedCallback() {
    this.menuObserver?.disconnect();
  }

  private updateNavItems(): void {
    this.navItemElements = Array.from(this.host.querySelectorAll('groupui-local-top-navigation-item'));
    this.navItemElements.forEach((el) => el.setAttribute('size', this.size));

    this.removeItemsInsideMenus();

    const initialActiveIndex = this.navItemElements.findIndex((item) => item.hasAttribute('active'));
    if (initialActiveIndex >= 0) {
      this.setActiveItem(initialActiveIndex);
    }
  }

  private removeItemsInsideMenus() {
    this.navItemElements = this.navItemElements.filter((item) => !item.closest('groupui-menu'));
  }

  private setActiveItem(index: number): void {
    if (index === this.activeItemIndex) return;

    this.navItemElements.forEach((el) => el.removeAttribute('active'));

    if (index >= 0 && index < this.navItemElements.length) {
      this.navItemElements[index].setAttribute('active', '');
      this.activeItemIndex = index;
    } else {
      this.activeItemIndex = -1;
    }
  }

  @Listen('click')
  handleClick(event: Event): void {
    const target = (event.target as HTMLElement).closest('groupui-local-top-navigation-item');

    if (!target || this.manualMode) {
      return;
    }
    const clickedItemIndex = this.navItemElements.indexOf(target as HTMLGroupuiLocalTopNavigationItemElement);
    if (clickedItemIndex >= 0) {
      this.setActiveItem(clickedItemIndex);
      this.groupuiChange.emit();
      this.host.dispatchEvent(new window.Event('change'));
    }
  }

  private handleSlotChange = (e: Event): void => {
    e.stopPropagation();
    this.updateNavItems();
    observeAllMenus(this.host, this.menuObserver);
  };

  render() {
    return (
      <Host>
        <nav {...this.ariaAttributes}>
          <slot onSlotchange={this.handleSlotChange}></slot>
        </nav>
      </Host>
    );
  }
}
